challenge.solution:
from 캐릭터 import 몬스터
몬스터들 = []
for i in range(3):
    이름, 힘 = input("이름과 힘: ").split()
    몬스터들.append(몬스터(이름, int(힘)))
for 하나 in 몬스터들:
    print(하나.소개())
가장 = 몬스터들[0]
for 하나 in 몬스터들:
    if 하나.힘 > 가장.힘:
        가장 = 하나
print(f"가장 센 몬스터 {가장.이름}")
